beforeExample:
import org.eclipse.swt.widgets.Listener;
import org.eclipse.swt.widgets.Event;

public class MyClass {
    public void myMethod(Listener someListener) {
        if (someListener instanceof Listener) {
            System.out.println("Listener is not null");
            someListener.handleEvent(new Event());
        }
    }
}

afterExample:
import org.eclipse.swt.widgets.Listener;
import org.eclipse.swt.widgets.Event;

public class MyClass {
    public void myMethod(Listener someListener) {
        if (someListener != null) {
            System.out.println("Listener is not null");
            someListener.handleEvent(new Event());
        }
    }
}

negativeExample:
import org.eclipse.swt.widgets.Listener;
import org.eclipse.swt.widgets.Event;

public class MyClass {
    public void myMethod(Object someObject) {
        // Here, someObject is not statically known to be a Listener, so instanceof is not redundant.
        if (someObject instanceof Listener) {
            System.out.println("Object is a Listener");
            ((Listener) someObject).handleEvent(new Event());
        }
    }
}
